#include "game_engine.hpp"
namespace remora {
void GameEngine::snakeFood(){std::vector<int>free;for(int n=0;n<s.cols*s.rows;n++)if(!has(s.body,n)&&!has(s.rocks,n))free.push_back(n);if(free.empty()){clear();return;}s.food=free[rnd(free.size())];}
void GameEngine::snake(){s.cols=26;s.rows=13;int head=6*s.cols+5;s.body={head,head-1,head-2};std::vector<int>choices;for(int n=0;n<s.cols*s.rows;n++)if(n%s.cols>10&&n%s.cols<s.cols-2&&n/s.cols>1&&n/s.cols<s.rows-2)choices.push_back(n);shuffle(choices);s.rocks.assign(choices.begin(),choices.begin()+(hard()?std::min(24,4+s.difficulty*2+stage()):0));s.dir=s.nextDir=3;s.goal=3+s.difficulty/2;s.tickMs=std::max(90,int(std::lround((int[]){270,225,185,155,130}[s.difficulty]*pace())));snakeFood();s.phase=Phase::Snake;later(s.tickMs,[this]{snakeTick();});}
void GameEngine::snakePress(int n){if(n==4)n=1;else if(n==6)n=3;else if(n!=2&&n!=5)return;if((n!=1&&n!=2&&n!=3&&n!=5)||s.nextDir!=s.dir)return;int opposite=s.dir==1?3:s.dir==3?1:s.dir==2?5:2;if(n!=opposite)s.nextDir=n;}
void GameEngine::snakeTick(){if(s.phase!=Phase::Snake)return;int head=s.body.front(),x=head%s.cols+(s.nextDir==1?-1:s.nextDir==3?1:0),y=head/s.cols+(s.nextDir==2?-1:s.nextDir==5?1:0);if(s.difficulty<3){x=(x+s.cols)%s.cols;y=(y+s.rows)%s.rows;}int next=y*s.cols+x;bool eating=next==s.food;auto end=s.body.end()-(eating?0:1);if(x<0||x>=s.cols||y<0||y>=s.rows||has(s.rocks,next)||std::find(s.body.begin(),end,next)!=end){fail("ULAR SAPI MENABRAK");return;}s.dir=s.nextDir;s.body.insert(s.body.begin(),next);if(eating){s.eaten++;points(35);if(sound)sound("food");if(s.eaten>=s.goal){clear();return;}snakeFood();}else s.body.pop_back();later(s.tickMs,[this]{snakeTick();});}
void GameEngine::pongBall(){float angle=(random()<.5?-1:1)*(.3+random()*.25);s.rally=0;s.bx=160;s.by=82;s.vx=std::sin(angle)*s.baseSpeed;s.vy=std::cos(angle)*s.baseSpeed;s.aiTarget=160;s.aiError=(random()-.5)*s.aiErrorRange;}
void GameEngine::pong(){int d=s.difficulty;s.width=(int[]){52,46,40,34,28}[d];s.aiWidth=(int[]){48,50,52,54,56}[d];s.goal=std::min(12,(int[]){3,4,5,6,7}[d]+burden());s.lives=(int[]){3,3,2,2,1}[d];s.baseSpeed=(float[]){4,4.8,5.7,6.6,7.5}[d]/pace();s.maxSpeed=std::min(17.f,(float[]){7.6,8.6,9.6,10.6,11.8}[d]/pace());s.aiSpeed=std::min(9.f,(float[]){3.3,4,4.8,5.7,6.6}[d]/pace());s.aiReaction=(int[]){10,8,6,4,3}[d];s.aiErrorRange=(int[]){46,34,22,14,6}[d];pongBall();s.phase=Phase::Pong;later(40,[this]{pongTick();});}
void GameEngine::pongBounce(bool opponent){float offset=(s.bx-(opponent?s.aiX:s.playerX))/((opponent?s.aiWidth:s.width)/2),aim=opponent?(s.playerX<160?1:-1)*(.35+s.difficulty*.1)+offset*.2:offset*.92+((s.held[3]?1:0)-(s.held[1]?1:0))*.1,angle=std::clamp(aim,-1.f,1.f),speed=std::min(s.maxSpeed,float(std::hypot(s.vx,s.vy)*1.035));s.vx=std::sin(angle)*speed;s.vy=std::cos(angle)*speed*(opponent?1:-1);s.rally++;if(!opponent){points(5);s.aiError=(random()-.5)*s.aiErrorRange;}if(sound)sound("bounce");}
void GameEngine::pongPress(int n){if(n==1||n==3)s.playerX=std::clamp(s.playerX+(n==1?-14:14),18+s.width/2,302-s.width/2);}
void GameEngine::pongTick(){if(s.phase!=Phase::Pong)return;s.tick++;s.playerX=std::clamp(s.playerX+((s.held[3]?1:0)-(s.held[1]?1:0))*8,18+s.width/2,302-s.width/2);if(s.tick%s.aiReaction==1||s.tick==1){if(s.vy<0){float impact=s.bx+s.vx*std::max(0.f,(s.by-51)/-s.vy),fold=std::fmod(std::fmod(impact-22,552.f)+552,552.f);s.aiTarget=22+(fold<=276?fold:552-fold)+s.aiError;}else s.aiTarget=160+(s.bx-160)*.2;}float half=s.aiWidth/2;s.aiX=std::clamp(s.aiX+std::clamp(s.aiTarget-s.aiX,-s.aiSpeed,s.aiSpeed),18+half,302-half);int steps=std::max(1,int(std::ceil(std::max(std::abs(s.vx),std::abs(s.vy))/3)));for(int i=0;i<steps;i++){float old=s.by;s.bx+=s.vx/steps;s.by+=s.vy/steps;if(s.bx<22||s.bx>298){s.bx=s.bx<22?44-s.bx:596-s.bx;s.vx*=-1;if(sound)sound("bounce");}if(s.vy<0&&old>=51&&s.by<=51&&std::abs(s.bx-s.aiX)<half+3){s.by=102-s.by;pongBounce(true);}if(s.vy>0&&old<=150&&s.by>=150&&std::abs(s.bx-s.playerX)<s.width/2+3){s.by=300-s.by;pongBounce(false);}}if(s.by<33){s.hits++;points(65);if(sound)sound("food");if(s.hits>=s.goal){clear();return;}pongBall();}if(s.by>168){s.lives--;if(sound)sound("damage");if(s.lives<=0){fail("BOLA SUSU TERLEWAT");return;}pongBall();}later(40,[this]{pongTick();});}
}
